#!/usr/bin/env node
/* Books-2 VASC1: vascular surgery + CTVS without textbooks (Rutherford/Kirklin
 * never arrived). Grounded in named standard sources: SVS and ESVS guidelines,
 * ACC/AHA and ESC guidelines, STS and EACTS guidance, NICE where it covers the
 * point, Indian practice labelled, landmark trials named correctly. All text in
 * own words. No milligram regimens anywhere; every threshold is tied to a named
 * guideline and recorded in the item source field.
 * 5 taxonomy gaps: sva-arterial, sva-venous-access, sct-coronary-valve,
 * sct-aorta-congenital, sct-thoracic. 5 lessons + 5 KB + 50 MCQs bk2-vas-001..050.
 * Overlay subject: surgery (already in the maikbook2 test loop; prep.js surgery
 * wiring unchanged per PLAS1/URO1 precedent). Paediatric cardiac needs nothing:
 * ped-congenital-heart, ped-acquired-heart and pcd-congenital already carry
 * maikbook2 items. */
import fs from "node:fs";
import path from "node:path";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
const require = createRequire(import.meta.url);
const LP = require("../prep-lessons.js");
const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), "..");
const REF_VASC = "SVS/ESVS/Global Vascular Guidelines, ESVS AAA/carotid/mesenteric guidance, AHA/ACC PAD guidance and BEST-CLI/BASIL-2/EVAR-1/NASCET/CREST trials (topic map; text rewritten, no verbatim copy)";
const REF_VEN = "ESVS chronic venous disease guidance, NICE varicose veins NG13, ACCP antithrombotic guidance, KDOQI vascular access, IWGDF diabetic foot and ISL lymphoedema consensus (topic map; text rewritten, no verbatim copy)";
const REF_CTV = "ESC/EACTS myocardial revascularisation and valvular guidance, ACC/AHA valvular and coronary guidance, STS guidance, ESC endocarditis guidance, ISHLT transplant guidance and SYNTAX/FREEDOM/ART/PARTNER/COAPT trials (topic map; text rewritten, no verbatim copy)";
const REF_AOR = "ESC aortic disease guidance, ACC/AHA aortic guidance, STS/EACTS congenital guidance and IRAD data (topic map; text rewritten, no verbatim copy)";
const REF_THO = "NICE lung cancer NG122, BTS pleural/pneumothorax guidance, ESTS/STS practice, ATLS and CROSS/JCOG0802/CALGB trials (topic map; text rewritten, no verbatim copy)";
function mcq(id, q, o, a, exp, r, kp, source) { return { id, q, o, a, exp, r, kp, source }; }
function step(tx, say, vis) { return vis ? { tx, say, vis } : { tx, say, vis: null }; }
const M = [];
function add(id, title, REF, kb, kbName, aliases, system, specialty, steps, pearls, patho, diffs, invs, mcqs) { M.push({ id, title, REF, kb, kbName, aliases, system, specialty, steps, pearls, patho, diffs, invs, mcqs }); }

