const SUBJECT = "surgery";
const SUBJECT_DIR = path.join(ROOT, "prep/overlays/maikbook2", SUBJECT);
const KB_DIR = path.join(ROOT, "kb/reference");
const LESSON_DIR = path.join(ROOT, "prep/lessons/v1");
const MODEL = "muse (local authoring, no external API)";
const ITEM_META = { prov: "SMD", gen: "hand", set: "maikbook2", d: 1, cog: "recall", credit: "StewardMD original medical knowledge base", licence: "CC BY 4.0 (StewardMD original)", licenceStandard: "CC BY 4.0", licenseUrl: "https://creativecommons.org/licenses/by/4.0", quality: { status: "automated_checks_passed", gates: { author_self_check: { note: "Author-verified against named guideline and trial sources" } } } };
fs.mkdirSync(SUBJECT_DIR, { recursive: true });
const normStem = (s) => String(s).toLowerCase().replace(/[^a-z ]/g, "").replace(/\s+/g, " ").trim();
// Blind cross-family check: every existing stem across all overlay families.
const familyStems = new Set();
{
  const ovRoot = path.join(ROOT, "prep/overlays");
  for (const set of fs.readdirSync(ovRoot)) {
    const sd = path.join(ovRoot, set);
    if (!fs.statSync(sd).isDirectory()) continue;
    for (const subj of fs.readdirSync(sd)) {
      const jd = path.join(sd, subj);
      if (!fs.statSync(jd).isDirectory()) continue;
      for (const f of fs.readdirSync(jd)) {
        if (!f.endsWith(".json")) continue;
        try {
          const d = JSON.parse(fs.readFileSync(path.join(jd, f), "utf8"));
          for (const it of (d.items || [])) if (it && it.q) familyStems.add(normStem(it.q));
        } catch { /* ignore unreadable */ }
      }
    }
  }
}
const seenIds = new Set();
const seenStems = new Set();
let failures = 0, written = 0, kbWritten = 0, kbSkipped = 0;
const ansDist = [0, 0, 0, 0];
for (const m of M) {
  if (m.mcqs.length !== 10) { console.error("COUNT", m.id, m.mcqs.length); failures++; }
  const lf = path.join(LESSON_DIR, m.id + ".json");
  if (fs.existsSync(lf)) { console.error("ORPHAN-EXISTS", m.id, "(expected lesson-less; refusing overwrite)"); failures++; continue; }
  const steps = m.steps.map((s) => JSON.parse(JSON.stringify(s)));
  for (const s of steps) {
    const words = s.tx.split(/\s+/).filter(Boolean).length;
    if (words < 40 || words > 90) { console.error("FAIL", m.id, words); failures++; }
    if (s.say === s.tx) { console.error("SAYEQ", m.id); failures++; }
  }
  for (const q of m.mcqs) {
    if (seenIds.has(q.id)) { console.error("DUPID", q.id); failures++; }
    seenIds.add(q.id);
    if (!(q.q && q.q.length > 20 && q.o.length === 4 && q.a >= 0 && q.a < 4 && q.exp && q.exp.length > 20 && q.r.length === 4 && q.kp && q.kp.length > 5)) { console.error("MCQSHAPE", m.id, q.id); failures++; }
    if (!q.source || q.source.length < 10) { console.error("NOSOURCE", m.id, q.id); failures++; }
    const sk = normStem(q.q);
    if (seenStems.has(sk)) { console.error("DUPSTEM", q.id); failures++; }
    seenStems.add(sk);
    if (familyStems.has(sk)) { console.error("XFAMILY", m.id, q.id); failures++; }
    if (/mg\b|milligram|mcg|microgram|\b\d+\s*(mg|g|ml|units?)\b/i.test(q.q + " " + q.exp)) { console.error("DOSE", m.id, q.id); failures++; }
  }
  const quiz = m.mcqs.map((q) => q.id);
  const lesson = {
    v: 1, module: m.id, subject: SUBJECT, title: m.title, minutes: steps.length + 2,
    steps, quiz, src: [], refs: [m.REF], gen: "AI", run: "books2-vasc1", model: MODEL,
    checks: { shape: true, numbers: true, drugs: true, verbatim: true, dashes: true, verify: true, redone: 0, dropped: 0, kbWords: 0, itemN: m.mcqs.length },
  };
  const probs = LP.checkLesson(lesson);
  if (probs.length) { console.error("LESSON FAIL", m.id, JSON.stringify(probs)); failures++; continue; }
  fs.writeFileSync(lf, JSON.stringify(lesson, null, 2) + "\n");
  written++;
  const kbPath = path.join(KB_DIR, m.kb + ".json");
  if (m.kb !== m.kb.replace(/\.json$/, "")) { console.error("KBID", m.kb); failures++; }
  if (!(m.kbName && m.kbName.length > 5 && m.aliases.length >= 4 && m.pearls.length >= 4 && m.patho.length > 50 && m.diffs.length >= 4 && m.invs.length >= 4)) { console.error("KBSHAPE", m.kb); failures++; }
  if (!fs.existsSync(kbPath)) {
    fs.writeFileSync(kbPath, JSON.stringify({ id: m.kb, name: m.kbName, aliases: [...m.aliases], class: "non_infective", system: m.system, specialty: m.specialty, referenceOnly: true, review: { status: "ai_drafted", reviewedBy: null, reviewedAt: null, clinicianApproved: false }, reference: { source: m.REF, sourceEdition: "Guideline-topic grounding, no textbook (2026-10-14)", pages: null, clinicalPearls: [...m.pearls], pathophysiology: m.patho, additionalDifferentials: [...m.diffs], additionalInvestigations: [...m.invs] } }, null, 2) + "\n");
    kbWritten++;
  } else kbSkipped++;
  const items = m.mcqs.map((q, i) => {
    const rot = (arr, k) => arr.map((_, j) => arr[(j + k) % arr.length]);
    const r = (i + M.indexOf(m)) % 4;
    ansDist[(q.a - r + 4) % 4]++;
    return { ...ITEM_META, ...q, o: rot(q.o, r), r: rot(q.r, r), a: (q.a - r + 4) % 4, topic: m.id };
  });
  for (const it of items) {
    if (!(it.o.length === 4 && it.a >= 0 && it.a < 4 && it.r.length === 4)) { console.error("ROT", m.id, it.id); failures++; }
    if (!it.source || it.source.length < 10) { console.error("ROTSOURCE", m.id, it.id); failures++; }
  }
  fs.writeFileSync(path.join(SUBJECT_DIR, m.id + ".json"), JSON.stringify({ topic: m.id, set: "maikbook2", v: 1, items }, null, 2) + "\n");
}
let idx = JSON.parse(fs.readFileSync(path.join(LESSON_DIR, "index.json"), "utf8"));
for (const m of M) idx.modules[m.id] = { title: m.title, minutes: m.steps.length + 2, steps: m.steps.length, gen: "AI" };
fs.writeFileSync(path.join(LESSON_DIR, "index.json"), JSON.stringify(idx, null, 1) + "\n");
let counts = JSON.parse(fs.readFileSync(path.join(ROOT, "prep/bank/overlay-counts.json"), "utf8"));
counts.sets.maikbook2[SUBJECT] = counts.sets.maikbook2[SUBJECT] || {};
for (const m of M) counts.sets.maikbook2[SUBJECT][m.id] = m.mcqs.length;
fs.writeFileSync(path.join(ROOT, "prep/bank/overlay-counts.json"), JSON.stringify(counts, null, 1) + "\n");
let tc = fs.readFileSync(path.join(ROOT, "test/prep-books-mcqs.test.mjs"), "utf8");
if (!tc.includes('"surgery"')) { console.error("SUBJLOOPUNKNOWN"); process.exit(1); }
const tm = tc.match(/assert\.equal\(totalItems, (\d+), "Expected (\d+) high-yield verified MCQs in maikbook2 \((.+)\)"\);/);
if (!tm || Number(tm[1]) !== Number(tm[2])) { console.error("BASEUNKNOWN"); process.exit(1); }
{
  const base = Number(tm[1]);
  const msg = tm[3] + " + 50 vascular-CTVS surgery";
  tc = tc.replace(tm[0], `assert.equal(totalItems, ${base + 50}, "Expected ${base + 50} high-yield verified MCQs in maikbook2 (${msg})");`);
}
fs.writeFileSync(path.join(ROOT, "test/prep-books-mcqs.test.mjs"), tc);
let qfail = 0;
for (const m of M) {
  const ov = JSON.parse(fs.readFileSync(path.join(SUBJECT_DIR, m.id + ".json"), "utf8"));
  if (ov.topic !== m.id || ov.set !== "maikbook2" || ov.v !== 1 || ov.items.length !== 10) { console.error("OVMISMATCH", m.id); qfail++; }
  const oids = ov.items.map((x) => x.id).sort().join(",");
  const qids = [...m.mcqs.map((q) => q.id)].sort().join(",");
  if (oids !== qids) { console.error("QUIZMISMATCH", m.id); qfail++; }
  const les = JSON.parse(fs.readFileSync(path.join(LESSON_DIR, m.id + ".json"), "utf8"));
  const lids = [...les.quiz].sort().join(",");
  if (lids !== qids) { console.error("LESSONQUIZMISMATCH", m.id); qfail++; }
}
console.log("modules:", M.length, "mcqs:", M.reduce((n, m) => n + m.mcqs.length, 0), "lessons:", written, "kbWritten:", kbWritten, "kbSkipped:", kbSkipped, "ansDist:", ansDist.join("/"), "failures:", failures, "mismatch:", qfail);
if (failures || qfail) process.exit(1);
